#!/bin/bash
# Fake Claude CLI for smoke tests (no real AI calls)
if [ "$1" = "--version" ]; then echo "2.1.296 (Claude Code)"; exit 0; fi
if [[ "$*" == *"--output-format json"* ]]; then echo '{"type":"result","result":"{\"name\":\"Test Bot\",\"job\":\"test\"}"}'; exit 0; fi
# v1.6 queue test: a message containing "slowtask" takes 3 s; reply echoes the message
trap 'kill $! 2>/dev/null; exit 130' INT TERM
last="${@: -1}"; [[ "$last" == *slowtask* ]] && { sleep 7 & wait $!; }
[[ "$last" == *sessiontest* && "$*" == *--resume* ]] && { echo "No conversation found with session ID: t1" >&2; exit 1; }
if [[ "$last" == *yaadtest* ]]; then echo '{"type":"assistant","message":{"content":[{"type":"text","text":"Theek hai\n🧠 MEMORY+: GST 18% alag dikhana\n🧠 MEMORY+ shared: Saurabh Nigam partner hai"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *memcheck* ]]; then m=no; [[ "$*" == *"GST 18% alag dikhana"* && "$*" == *"Saurabh Nigam partner"* ]] && m=yes; echo '{"type":"assistant","message":{"content":[{"type":"text","text":"memory seen '$m'"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *codetest* ]]; then echo '{"type":"assistant","message":{"content":[{"type":"text","text":"Yeh raha:\n```\nPOINT SIX TEXT\n```\nDone **ok**"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *"WATCH MODE check"* ]]; then echo '{"type":"assistant","message":{"content":[{"type":"text","text":"NO_NEW"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
[[ "$*" == *"--resume t1"* ]] && { echo "Error: --resume requires a valid session ID or session title when used with --print." >&2; exit 1; }
if [[ "$last" == *schedtest* ]]; then echo '{"type":"assistant","message":{"content":[{"type":"text","text":"Theek hai.\n⏰ SCHEDULE+: 9:30, 10:10 | Mon-Sat | WhatsApp Sambhav: office timing"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *partest* ]]; then f=no; [[ "$*" == *"--fork-session"* ]] && f=yes; echo '{"type":"assistant","message":{"content":[{"type":"text","text":"par answer fork '$f'"}]}}'; echo '{"type":"result","subtype":"success","session_id":"22222222-2222-2222-2222-222222222222","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *slowprogress* ]]; then echo '{"type":"system","subtype":"init","session_id":"11111111-1111-1111-1111-111111111111","tools":[]}'; echo '{"type":"assistant","message":{"content":[{"type":"text","text":"step one done"}]}}'; sleep 7 & wait $!; echo '{"type":"assistant","message":{"content":[{"type":"text","text":"all done"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *submittest* ]]; then echo '{"type":"assistant","message":{"content":[{"type":"text","text":"Pack ready.\n📤 SUBMIT-REQUEST: DOC-12 rev B to ISA | upload icloud/en/DOC-12_revB.pdf, title DOC-12"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
if [[ "$last" == *"GUEST Ritvik"* ]]; then ok=no; [[ "$*" == *"--disallowedTools"* && "$*" == *"mcp__toshicrm"* && "$*" != *"--allowedTools"* ]] && ok=yes; echo '{"type":"assistant","message":{"content":[{"type":"text","text":"guestmode '$ok'"}]}}'; echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[]}'; exit 0; fi
[[ "$last" == *failtest* ]] && { echo "Claude usage limit reached (fake)" >&2; exit 1; }
echo '{"type":"system","subtype":"init","session_id":"11111111-1111-1111-1111-111111111111","tools":["Read","mcp__playwright__browser_click","mcp__claude_ai_Gmail__send_message"]}'
echo '{"type":"assistant","message":{"content":[{"type":"text","text":"Smoke test reply: '"${last//[^a-z0-9 ]/}"'"}]}}'
echo '{"type":"result","subtype":"success","session_id":"11111111-1111-1111-1111-111111111111","permission_denials":[],"total_cost_usd":0.01,"num_turns":1}'
